const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1Z',book:'M4 4h7a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H4Zm16 0h-3a3 3 0 0 0-3 3v14a3 3 0 0 1 3-3h3Z',review:'m8 12 3 3 6-7M5 3h14v18H5Z',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',org:'M9 3h6v5H9Zm-6 14h6v5H3Zm12 0h6v5h-6ZM12 8v5M6 17v-4h12v4',plug:'m8 3 1 5m7-5-1 5M6 8h12v3a6 6 0 0 1-6 6v5M6 8v3a6 6 0 0 0 6 6',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',activity:'M2 12h5l3-8 4 16 3-8h5',bridge:'M3 17h18M5 17V7m14 10V7M5 9c4 5 10 5 14 0M9 12v5m6-5v5',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm6-2 6 6',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6Zm-4 9 3 3 5-6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Zm0-16v6l4 2',code:'m8 5-6 7 6 7m8-14 6 7-6 7m-5 1 2-16',link:'m10 14 4-4M9 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 10a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',check:'m4 12 5 5L20 6',user:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10ZM3 22a9 9 0 0 1 18 0',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M18 6 6 18'};
const icon=(name,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const btn=(label,action,extra='',cls='',symbol='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${symbol?icon(symbol):''}${label}</button>`;
const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
const kindIcon=k=>({knowledge:'book',standard:'shield',skill:'code',app:'grid'}[k]||'book');
const stateColor=s=>['certified','approved','active','ready'].includes(s)?'green':['pending','needs_review','expired','changes_requested','budget_exceeded'].includes(s)?'amber':['rejected','retired','needs_clarification'].includes(s)?'red':'grey';
const label=s=>String(s||'').replaceAll('_',' ');
const date=v=>v?new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const initials=s=>s.split(' ').map(x=>x[0]).slice(0,2).join('');
let boot=null,view='overview',filter='all',query='',kindFilter='all',demoUser=sessionStorage.getItem('dc_demo_user')||'paul',token='',packet=null,sourceResults={},bridgeConfig=null;
const names={overview:'Overview',knowledge:'Knowledge registry',reviews:'Promotion reviews',context:'Context playground',org:'Organization & tethers',sources:'Source connections',apps:'App gallery',activity:'Activity log',bridge:'Bifrost delivery'};
const userName=id=>boot.users.find(x=>x.id===id)?.name||id;
const scopeName=id=>boot.units.find(x=>x.id===id)?.name||(id===boot.user.id?'Only you':userName(id));
const assetStatus=a=>a.effectiveStatus||a.status;
const unitKind=id=>boot.units.find(x=>x.id===id)?.kind||'personal';
const getAsset=id=>boot.assets.find(x=>x.id===id);
const tagHTML=ts=>ts.map(t=>`<span class="tag">${esc(t)}</span>`).join('');
const header=(eyebrow,title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('spark')}<strong>${title}</strong><p>${desc}</p>${action}</div>`;
async function api(path,body,method=body===undefined?'GET':'POST'){
  const response=await fetch(`/api${path}`,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{'X-Demo-User':demoUser})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result;
}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5500);}
async function refresh(){boot=await api('/bootstrap');render();}
function navigate(next){view=next;filter='all';query='';kindFilter='all';history.replaceState(null,'',`#${next}`);render();window.scrollTo({top:0,behavior:'smooth'});}
function modal(title,subtitle,body,footer='',eyebrow='DREAMCATCHER CONTEXT'){$('#modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();}
function shell(content){
  const pending=boot.proposals.filter(p=>p.status==='pending').length;
  const nav=(key,name,symbol)=>`<button title="${name}" aria-label="${name}" data-action="nav" data-view="${key}" class="${view===key?'active':''}">${icon(symbol)}<span>${name}</span>${key==='reviews'&&pending?`<span class="count">${pending}</span>`:''}</button>`;
  return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div>dreamcatcher<small>CONTEXT</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav">${nav('overview','Overview','home')}${nav('knowledge','Knowledge','book')}${nav('reviews','Promotion reviews','review')}${nav('context','Context playground','spark')}</nav><div class="nav-label">ECOSYSTEM</div><nav class="nav">${nav('org','Organization & tethers','org')}${nav('sources','Source connections','plug')}${nav('apps','App gallery','grid')}${nav('bridge','Bifrost delivery','bridge')}${nav('activity','Activity log','activity')}</nav><div class="sidebar-foot"><span><i class="live-dot"></i>Context service online</span><div class="tiny muted" style="margin-top:5px">Workspace v1.0 · local persistence</div></div></aside><div class="main"><header class="topbar"><div class="crumb"><span>Dreamcatcher</span><span class="slash">/</span><strong>${names[view]}</strong></div><div class="top-actions"><span class="workspace-label">${esc(scopeName(boot.user.unitId))} workspace</span><div class="profile"><span class="avatar">${initials(boot.user.name)}</span>${boot.mode==='demo'?`<select id="identity" aria-label="Demo identity">${boot.users.map(u=>`<option value="${esc(u.id)}" ${u.id===boot.user.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`:`<span class="small">${esc(boot.user.name)}</span>`}</div></div></header>${boot.mode==='demo'?`<div class="demo-bar"><span><strong>EXPLORATION WORKSPACE</strong> · Synthetic people, policies, and source records</span><button data-action="demo-help">Try the manager review flow ${'↗'}</button></div>`:''}<main class="page" id="page-content">${content}</main></div></div>`;
}
function render(){const fn={overview:overviewView,knowledge:knowledgeView,reviews:reviewsView,context:contextView,org:orgView,sources:sourcesView,apps:appsView,activity:activityView,bridge:bridgeView};$('#app').innerHTML=shell((fn[view]||overviewView)());}

function constellation(){return `<svg viewBox="0 0 480 300" role="img" aria-label="Personal, team, department and organization knowledge connected by scope"><defs><radialGradient id="halo"><stop stop-color="#b9a0ff" stop-opacity=".18"/><stop offset="1" stop-color="#b9a0ff" stop-opacity="0"/></radialGradient></defs><circle cx="255" cy="155" r="140" fill="url(#halo)"/><g fill="#c8b8ea" opacity=".42"><circle cx="30" cy="55" r="1"/><circle cx="170" cy="31" r="1.3"/><circle cx="324" cy="38" r="1"/><circle cx="430" cy="95" r="1.5"/><circle cx="385" cy="259" r="1"/><circle cx="117" cy="261" r="1.5"/><circle cx="397" cy="185" r=".8"/><circle cx="65" cy="198" r="1"/><circle cx="260" cy="269" r="1"/><circle cx="447" cy="245" r="1"/></g><g fill="none" stroke="#7c659e" stroke-width="1"><path d="m110 217 109-65 114 48 40-116-154 68 30-91 124 23"/><path d="m110 217 139-156 84 139" opacity=".35" stroke-dasharray="3 5"/></g><g class="node" data-action="scope" data-scope="personal"><circle cx="110" cy="217" r="20" fill="#322b48" stroke="#ac8bdb"/><circle cx="110" cy="217" r="5" fill="#d9b8ff"/><text x="110" y="257" fill="#b9adc9" text-anchor="middle" font-size="11">INDIVIDUAL</text></g><g class="node" data-action="scope" data-scope="team"><circle cx="219" cy="152" r="32" fill="#302a46" stroke="#a68acd"/><circle cx="219" cy="152" r="22" fill="none" stroke="#77608f" stroke-dasharray="2 4"/><path d="m211 152 6 6 11-13" fill="none" stroke="#d7c2fa" stroke-width="2"/><text x="219" y="205" fill="#ddc8f4" text-anchor="middle" font-size="11">TEAM</text></g><g class="node" data-action="scope" data-scope="department"><circle cx="333" cy="200" r="19" fill="#242b3d" stroke="#898db1"/><circle cx="333" cy="200" r="4" fill="#aab5e0"/><text x="333" y="238" fill="#a7abc5" text-anchor="middle" font-size="10">DEPARTMENT</text></g><g class="node" data-action="scope" data-scope="organization"><circle cx="373" cy="84" r="25" fill="#30263d" stroke="#aa8da7"/><circle cx="373" cy="84" r="5" fill="#e2b4c7"/><text x="373" y="44" fill="#c8b1c7" text-anchor="middle" font-size="10">ORGANIZATION</text></g><circle cx="249" cy="61" r="4" fill="#a996c8"/></svg>`;}
function overviewView(){
  const a=boot.assets,cert=a.filter(x=>assetStatus(x)==='certified'),privateCount=a.filter(x=>x.scopeId===boot.user.id).length,queue=boot.proposals.filter(x=>x.status==='pending');
  const stats=[['Available knowledge',a.filter(x=>x.kind!=='app').length,'Within your access scope','book'],['Certified standards',cert.filter(x=>x.kind==='standard').length,'Versioned and approved','shield'],['Awaiting review',queue.length,'Submitted knowledge packages','review'],['Source pathways',boot.connectors.length,'Live inventory + export adapters','plug']];
  return `<div class="section-head"><div class="eyebrow">YOUR KNOWLEDGE, IN CONTEXT</div><span class="small muted">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</span></div><section class="hero"><div class="hero-copy"><span class="preview-label">Connected knowledge. Considered authority.</span><h1>The right knowledge.<br>At the right level.</h1><p>Personal understanding, shared standards, and the context to know which one matters.</p><div class="button-row">${btn('Explore your context','nav','data-view="context"','primary','spark')}${btn('Add knowledge','new-item','','','plus')}</div></div><div class="hero-art">${constellation()}</div></section><div class="stats">${stats.map(([l,v,n,i])=>`<div class="stat"><div><div class="stat-label">${l}</div><div class="stat-value">${v.toString().padStart(2,'0')}</div><div class="stat-note">${n}</div></div>${icon(i)}</div>`).join('')}</div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Knowledge in motion</h2>${btn('View registry','nav','data-view="knowledge"','ghost sm','arrow')}</div>${a.filter(x=>x.kind!=='app').slice(0,4).map(x=>`<div class="row-link" role="button" tabindex="0" data-action="detail" data-id="${x.id}"><span class="tile-icon ${x.authority==='mandatory'?'green':''}">${icon(kindIcon(x.kind))}</span><div class="row-main"><strong>${esc(x.title)}</strong><small>${esc(scopeName(x.scopeId))} · ${label(x.kind)} · v${x.version}</small></div>${badge(label(assetStatus(x)),stateColor(assetStatus(x)))}</div>`).join('')||empty('A clean slate','Add personal knowledge to start building your context.')}</section><section class="panel"><div class="panel-head"><h2>Ready for a wider audience</h2>${badge(`${queue.length} pending`,queue.length?'amber':'grey')}</div>${queue.slice(0,2).map(p=>`<div class="row-link" role="button" tabindex="0" data-action="review" data-id="${p.id}"><span class="tile-icon amber">${icon('review')}</span><div class="row-main"><strong>${esc(p.proposed.title)}</strong><small>${esc(userName(p.submittedBy))} → ${esc(scopeName(p.targetId))}</small></div>${icon('chevron')}</div>`).join('')||empty('No pending promotions','Submit a knowledge package when it is ready for your team.') }<div class="panel-pad"><div class="small" style="color:#c5b3e3;margin-bottom:8px">A review, not a silent handoff.</div><p class="small muted" style="margin:0">Compare the proposed change, check evidence, and let a manager or delegate certify its wider use.</p>${btn('Open review queue','nav','data-view="reviews"','ghost sm','arrow')}</div></section></div><div class="spacer"></div><div class="section-head"><div><h2>Start with a question</h2><p>See how context changes when intent changes.</p></div>${badge(`${privateCount} private items`,'grey')}</div><div class="grid2">${['Latest Jira tickets','How should I prepare reconciliation evidence?'].map((p,i)=>`<div class="panel row-link" role="button" tabindex="0" data-action="try-prompt" data-prompt="${p}"><span class="tile-icon">${icon(i?'shield':'user')}</span><div class="row-main"><strong>“${p}”</strong><small>${i?'Applicable standards constrain personal methods':'Your own work is the default focus'}</small></div>${icon('arrow')}</div>`).join('')}</div>`;
}
function knowledgeRows(){return boot.assets.filter(a=>a.kind!=='app'&&(filter==='all'||unitKind(a.scopeId)===filter)&&(kindFilter==='all'||a.kind===kindFilter)&&`${a.title} ${a.content} ${a.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));}
function registryTable(){const rows=knowledgeRows();return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Knowledge</th><th>Audience</th><th>Authority</th><th>Certification</th><th>Version</th></tr></thead><tbody>${rows.map(a=>`<tr tabindex="0" data-action="detail" data-id="${a.id}"><td><div class="title">${esc(a.title)}</div><div class="desc">${esc(a.content.split('\n')[0])}</div>${tagHTML(a.tags.slice(0,3))}</td><td>${esc(scopeName(a.scopeId))}<div class="tiny muted">${label(unitKind(a.scopeId))}</div></td><td>${badge(a.authority,a.authority==='mandatory'?'blue':'grey')}</td><td>${badge(label(assetStatus(a)),stateColor(assetStatus(a)))}</td><td class="muted">v${a.version}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching knowledge','Try a different audience, type, or search term.',btn('Add knowledge','new-item','','primary','plus'));}
function knowledgeView(){return `${header('KNOWLEDGE REGISTRY','A home for what you know.','Trace knowledge to its owner, source, audience, and approved version.',btn('Add knowledge','new-item','','primary','plus'))}<div class="toolbar"><label class="search">${icon('search')}<input id="knowledge-search" placeholder="Search knowledge, standards, or skills…" value="${esc(query)}" aria-label="Search knowledge"></label><select id="kind-filter" aria-label="Knowledge type"><option value="all">All types</option>${['knowledge','standard','skill'].map(x=>`<option ${x===kindFilter?'selected':''}>${x}</option>`).join('')}</select></div><div class="tabs">${['all','personal','team','department','organization'].map(x=>`<button data-action="filter" data-filter="${x}" class="${filter===x?'active':''}">${x==='all'?'All available':x==='personal'?'Only me':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><section class="panel" id="registry-table">${registryTable()}</section><div class="note-card"><strong>Scope is not a ranking rule.</strong> A broader audience makes knowledge applicable to more people. The context resolver still considers the request, personal relevance, certification, and explicit topic constraints.</div>`;}
function reviewsView(){const list=boot.proposals.filter(p=>filter==='all'||p.status===filter);return `${header('PROMOTION & CERTIFICATION','Make good knowledge shared practice.','Review the exact change before it becomes a team, department, or organization standard.')}<div class="tabs">${['all','pending','approved','changes_requested','rejected'].map(x=>`<button data-action="filter" data-filter="${x}" class="${filter===x?'active':''}">${x==='all'?'All reviews':label(x)}</button>`).join('')}</div><section class="panel">${list.length?list.sort((a,b)=>b.submittedAt.localeCompare(a.submittedAt)).map(p=>`<div class="row-link" role="button" tabindex="0" data-action="review" data-id="${p.id}"><span class="tile-icon ${p.status==='pending'?'amber':'green'}">${icon('review')}</span><div class="row-main"><strong>${esc(p.proposed.title)}</strong><small>${esc(userName(p.submittedBy))} · ${esc(scopeName(p.before.scopeId))} → ${esc(scopeName(p.targetId))} · ${date(p.submittedAt)}</small></div>${badge(label(p.status),stateColor(p.status))}${p.canReview&&p.status==='pending'?badge('Your review','blue'):''}${icon('chevron')}</div>`).join(''):empty('No reviews in this view','Promote an item from the knowledge registry when it is ready for a wider audience.',btn('Go to knowledge','nav','data-view="knowledge"','','arrow'))}</section><div class="grid2" style="margin-top:22px"><div class="note-card" style="margin:0"><strong>Managers and delegates approve.</strong><br>Review authority is scoped to the target audience. A submitter cannot approve their own proposal.</div><div class="note-card" style="margin:0"><strong>Every approval has a version.</strong><br>Source edits trigger a new review. Approved text and its decision history remain traceable.</div></div>`;}
function contextView(){return `${header('CONTEXT PLAYGROUND','Ask. Inspect. Understand.','See exactly which knowledge would reach the user’s AI tool, and why.') }<div class="context-grid"><form class="panel context-compose" id="resolve-form"><h2>What are you working on?</h2><span class="small muted">Resolving for ${esc(boot.user.name)}</span><textarea id="prompt" name="prompt" aria-label="Your request" placeholder="Latest Jira tickets" required>${esc(packet?.request||'')}</textarea><div class="form-field"><label for="focus">Retrieval focus</label><select id="focus" name="scope"><option value="auto">Automatic · follow intent</option><option value="personal">Individual</option><option value="team">Team</option><option value="department">Department</option><option value="organization">Organization</option></select></div><div class="form-field"><label for="context-app">App context</label><select id="context-app" name="appId"><option value="">No specific app</option>${boot.assets.filter(a=>a.kind==='app').map(a=>`<option value="${a.id}" ${packet?.appId===a.id?'selected':''}>${esc(a.title)}</option>`).join('')}</select></div><div class="form-field"><label for="budget">Context budget · approximate tokens</label><select id="budget" name="budget"><option>4000</option><option>8000</option><option>16000</option><option>500</option></select></div><button type="submit" class="btn primary full">${icon('spark')} Resolve context</button><hr class="separator"><div class="tiny muted">TRY A DIFFERENT INTENT</div>${['Latest Jira tickets','Latest tickets for my team','How should I prepare reconciliation evidence?','What is our workplace conduct standard?'].map(p=>`<button type="button" class="example" data-action="example" data-prompt="${p}">“${p}”</button>`).join('')}</form><section class="panel" id="resolution">${packet?packetView(packet):`<div class="resolve-empty"><div class="orbit">${icon('spark')}</div><h2>Context with a reason.</h2><p>Write a request to see personal relevance, applicable standards, source evidence, and a scoped tool plan.</p></div>`}</section></div>`;}
function evidenceView(a){return `<div class="evidence"><h3>${icon(kindIcon(a.kind))}<span>${esc(a.title)}</span></h3><div class="status-line">${badge(scopeName(a.scopeId),a.mandatory?'blue':'grey')}${badge(a.mandatory?'Required standard':a.tethered?'Tethered guidance':a.status==='private'?'Personal context':'Certified guidance',a.mandatory?'green':'grey')}<span class="tiny muted">v${a.version} · score ${a.score}</span></div><p>${esc(a.content)}</p><div class="why">${esc(a.why.join(' · '))}</div>${a.source?`<div class="tiny muted" style="margin-top:7px">Source: ${esc(a.source.connectorId)} · ${esc(a.source.externalId)} · revision ${esc(a.source.revision)}</div>`:''}</div>`;}
function packetView(p){return `<div class="resolution-top"><div class="status-line">${badge(p.status==='ready'?'Context ready':label(p.status),stateColor(p.status))}${badge(`${p.focus.scope} focus`,'blue')}</div><h2>${p.focus.scope==='personal'?'Start with your perspective.':`Focus on ${esc(p.focus.unitId?scopeName(p.focus.unitId):p.focus.scope)}.`}</h2><p>${esc(p.focus.reason)}</p><div class="resolution-metrics"><span>${p.mandatory.length+p.context.length} sources</span><span>${p.mandatory.length} applicable standards</span><span>~${p.estimatedTokens} tokens</span><span>${p.elapsedMs} ms · local resolution</span></div></div>${p.unavailableStandards?.length?`<div class="panel-pad"><div class="notice red">An applicable standard needs recertification: ${p.unavailableStandards.map(a=>esc(a.title)).join(', ')}. Ask its owner before giving a definitive procedural answer.</div></div>`:''}${p.overBudget?'<div class="panel-pad"><div class="notice red">Required standards exceed this budget. Increase it before composing an answer; standards were not silently dropped.</div></div>':''}${p.conflicts.length?`<div class="panel-pad">${p.conflicts.map(c=>`<div class="notice ${c.status==='needs_owner_review'?'red':'amber'}"><strong>${esc(c.key)}</strong><br>${esc(c.message)}<div style="margin-top:6px">${c.items.map(a=>`${esc(a.title)}: <strong>${esc(a.value)}</strong>`).join('<br>')}</div></div>`).join('')}</div>`:''}${p.toolPlan?`<div class="evidence"><h3>${icon('plug')} Scoped tool plan</h3><p>${esc(p.toolPlan.note)}</p><pre>${esc(p.toolPlan.query||'Group-to-source mapping required before query execution')}</pre><span class="tiny muted">Plan only · no upstream Jira request has been sent</span></div>`:''}${p.mandatory.length?`<div class="panel-head"><h2>Applicable standards</h2>${icon('shield')}</div>${p.mandatory.map(evidenceView).join('')}`:''}${p.context.length?`<div class="panel-head"><h2>Relevant context</h2>${icon('book')}</div>${p.context.map(evidenceView).join('')}`:''}${!p.context.length&&!p.mandatory.length?empty('No matching knowledge yet','No evidence was invented. Add relevant knowledge or connect a source.'):''}<details><summary>Why other visible items were excluded (${p.skipped.length})</summary><ul>${p.skipped.map(s=>`<li>${esc(s.title)} — ${esc(s.reason)}</li>`).join('')}</ul><p class="tiny muted">Items you cannot access never appear in this trace.</p></details><div class="panel-pad button-row">${btn('Export context JSON','export-packet','','','download')}${btn('View delivery instructions','packet-json','','ghost','code')}</div>`;}

function sourcesView(){return `${header('SOURCE CONNECTIONS','Find the knowledge you already have.','Discover accessible records, inspect the connection path, and import evidence privately.')}<div class="source-grid">${boot.connectors.map(c=>`<article class="source-card"><div class="source-top"><div class="source-mark" style="color:${c.color}">${c.mark}</div>${badge(c.capability==='live_inventory'?'Live inventory adapter':'Export adapter',c.capability==='live_inventory'?'blue':'grey')}</div><div class="eyebrow" style="font-size:9px;margin-bottom:6px">${c.category}</div><h2>${c.name}</h2><p>${c.description}</p><div class="source-route">${c.route}</div>${btn(c.baseUrl?'Inspect connection':'Set up connection','source',`data-id="${c.id}"`,'','arrow')}</article>`).join('')}</div><div class="note-card"><strong>Connected does not mean certified.</strong> Source imports start in your private workspace. Promotion requires an explicit submission and manager or delegate review. These adapters do not automatically synchronize upstream access changes.</div>`;}
function orgView(){const root=boot.units.find(x=>x.kind==='organization'),depts=boot.units.filter(x=>x.parentId===root?.id),node=u=>`<div class="org-node ${u.id===boot.user.unitId?'current':''}"><div class="node-kind">${u.kind}</div><h3>${esc(u.name)}</h3><small>${esc(userName(u.managerId))}</small>${u.id===boot.user.unitId?'<div class="tiny" style="color:#c7ade9;margin-top:6px">Your home scope</div>':''}</div>`;return `${header('ORGANIZATION & TETHERS','One home. Meaningful connections.','A defined reporting hierarchy, with deliberate bridges for shared knowledge.',btn('Propose tether','new-tether','','primary','link'))}<section class="panel"><div class="panel-head"><h2>Authority follows the organization</h2>${badge(boot.mode==='demo'?'Illustrative hierarchy':'Configured hierarchy','grey')}</div><div class="org-tree"><div class="org-root">${root?node(root):''}</div>${depts.map(d=>`<div class="org-branch">${node(d)}${boot.units.filter(x=>x.parentId===d.id).map(t=>`<div class="org-child">${node(t)}</div>`).join('')}</div>`).join('')}</div></section><div class="spacer"></div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Knowledge tethers</h2>${badge('Topic scoped','blue')}</div>${boot.tethers.length?boot.tethers.map(t=>`<div class="tether-row">${icon('link')}<div class="names"><strong>${esc(scopeName(t.fromId))} → ${esc(scopeName(t.toId))}</strong><div>${tagHTML(t.tags)}</div></div>${badge(t.status,stateColor(t.status))}${t.status==='pending'&&boot.managedUnits.includes(t.toId)&&t.createdBy!==boot.user.id?btn('Accept','accept-tether',`data-id="${t.id}"`,'sm primary'):''}${t.status!=='revoked'&&(boot.managedUnits.includes(t.fromId)||boot.managedUnits.includes(t.toId))?btn('Revoke','revoke-tether',`data-id="${t.id}"`,'sm ghost'):''}</div>`).join(''):empty('No tethers yet','Managers can propose specific topics to share with another scope.')}<div class="panel-pad small muted">Only certified items explicitly approved for tether sharing can cross a tether. Source-team mandates arrive as guidance.</div></section><section class="panel"><div class="panel-head"><h2>Approval delegates</h2>${btn('Appoint','new-delegate','','sm','plus')}</div><div class="panel-pad">${boot.delegations.length?boot.delegations.map(d=>`<div class="grant-row"><span class="avatar">${initials(userName(d.userId))}</span><div class="row-main"><strong>${esc(userName(d.userId))}</strong><small>${esc(scopeName(d.unitId))} · until ${date(d.expiresAt)}</small></div>${badge(d.status,stateColor(d.status))}${d.status==='active'&&boot.units.find(u=>u.id===d.unitId)?.managerId===boot.user.id?btn('Revoke','revoke-delegate',`data-id="${d.id}"`,'sm ghost'):''}</div>`).join(''):'<p class="small muted">No delegated reviewers in your scope.</p>'}<p class="small muted">Delegates approve within their assigned scope. They do not gain access to everyone’s private knowledge.</p></div></section></div>`;}
function appsView(){const apps=boot.assets.filter(a=>a.kind==='app');return `${header('DREAMCATCHER APP GALLERY','Tools with the right context.','Personal utilities and shared apps, with explicit audience and knowledge dependencies.',btn('Register app','new-app','','primary','plus'))}<div class="app-grid">${apps.map((a,i)=>`<article class="app-card"><div class="app-art ${['','blue','green'][i%3]}">${badge(unitKind(a.scopeId),'grey')}<div class="art-lines"></div>${icon(i%2?'activity':'grid')}<div class="art-title">${esc(a.tags.slice(0,2).join(' / ').toUpperCase())}</div></div><div class="app-info"><h2>${esc(a.title)}</h2><p>${esc(a.content)}</p><div class="status-line">${badge(label(assetStatus(a)),stateColor(assetStatus(a)))}<span class="tiny muted">${esc(scopeName(a.scopeId))}</span></div>${btn('Inspect app context','app-context',`data-id="${a.id}"`,'','spark')}${btn('Details & endorsement','detail',`data-id="${a.id}"`,'ghost sm')}</div></article>`).join('')||empty('No apps available','Register a personal app, then request broader endorsement.')}</div><div class="note-card"><strong>An endorsement describes intended use.</strong> It does not certify a code release or grant new data permissions. App context dependencies must be certified for the entire receiving audience before approval.</div>`;}
function activityView(){return `${header('ACTIVITY LOG','A trace of every meaningful decision.','Review submissions, approvals, source changes, and context resolutions visible to you.')}<section class="panel timeline">${boot.events.map(e=>`<div class="event"><span class="event-dot"></span><div><strong>${esc(label(e.type.replaceAll('.',' · ')))}</strong><p>${esc(e.detail)}</p><time>${esc(userName(e.actorId))} · ${new Date(e.at).toLocaleString()}</time></div></div>`).join('')||empty('Nothing to show yet','Your knowledge and review actions will appear here.')}</section>`;}
function bridgeView(){return `${header('BIFROST DELIVERY','One context service. Your AI of choice.','Expose authorized context through a standard MCP endpoint and a REST API.',btn('Export Bifrost config','export-bridge','','primary','download'))}<section class="panel"><div class="bridge-flow"><div class="bridge-step"><strong>Dreamcatcher Context</strong><span>Scope · knowledge · standards</span></div>${icon('arrow')}<div class="bridge-step"><strong>Bifrost</strong><span>Authenticated MCP routing</span></div>${icon('arrow')}<div class="bridge-step"><strong>Your AI tool</strong><span>Evidence for each request</span></div></div></section><div class="spacer"></div><div class="grid2"><section class="panel panel-pad"><div class="section-head"><h2>Available tools</h2>${badge('Read only','green')}</div>${[['resolve_context','Resolve a request with source evidence and authority.'],['search_knowledge','Search only knowledge the caller can access.'],['get_knowledge','Inspect a specific knowledge item and revision.'],['list_apps','Find available apps and their endorsements.']].map(([n,d])=>`<div class="grant-row"><div><code>${n}</code><div class="small muted">${d}</div></div></div>`).join('')}<div class="notice">Promotion and certification remain explicit human actions in this app.</div></section><section class="panel panel-pad"><h2 style="font-size:16px;font-weight:500;margin-top:0">Connect the gateway</h2><ol class="list-plain"><li>Run this service in the approved environment.</li><li>Register its <code>/mcp</code> endpoint in Bifrost.</li><li>Use a distinct, validated credential for each person.</li><li>Instruct the AI client to call <code>resolve_context</code> before work questions.</li></ol><div class="notice amber">MCP makes context available. It does not force every AI client to request it. Mandatory pre-answer injection needs a client hook or gateway middleware.</div>${btn('Inspect connection config','show-bridge','','','code')}<p class="tiny muted">Adapter target: Maxim Bifrost. Credentials and a live gateway were not supplied for this workspace.</p></section></div><div class="note-card"><strong>Identity comes from authentication.</strong> The context API does not accept a caller-selected user ID in its request body. The demo identity switch is disabled in authenticated deployments.</div>`;}

function detail(id){const a=getAsset(id);if(!a)return;const deps=a.dependencies.map(d=>getAsset(d)?.title||'Dependency not in current access scope');const target=a.scopeId===a.ownerId?boot.user.unitId:boot.units.find(u=>u.id===a.scopeId)?.parentId;
  modal(esc(a.title),`${label(a.kind)} · ${esc(scopeName(a.scopeId))} · version ${a.version}`,`<dl class="meta-grid"><div><dt>Authority</dt><dd>${badge(a.authority,a.authority==='mandatory'?'blue':'grey')}</dd></div><div><dt>Certification</dt><dd>${badge(label(assetStatus(a)),stateColor(assetStatus(a)))}</dd></div><div><dt>Owner</dt><dd>${esc(userName(a.ownerId))}</dd></div><div><dt>Approved by</dt><dd>${a.approvedBy==='seed'?'Synthetic seed':esc(a.approvedBy?userName(a.approvedBy):'Not certified')}</dd></div><div><dt>Valid through</dt><dd>${date(a.expiresAt)}</dd></div><div><dt>Tether sharing</dt><dd>${a.tetherable?'Eligible after certification':'Not enabled'}</dd></div></dl><div class="content-text">${esc(a.content)}</div><div style="margin-top:12px">${tagHTML(a.tags)}</div>${a.ruleKey?`<div class="notice">Explicit assertion: <code>${esc(a.ruleKey)}</code> = <strong>${esc(a.ruleValue)}</strong></div>`:''}${deps.length?`<div class="mini-label">Required knowledge</div><p class="small muted">${esc(deps.join(' · '))}</p>`:''}${a.source?`<div class="mini-label">Source provenance</div><pre>${esc(JSON.stringify(a.source,null,2))}</pre>`:''}${a.originId?`<div class="notice">Derived from a reviewed source snapshot · source version ${a.originVersion||1}</div>`:''}${a.launchUrl?`<a class="btn" href="${esc(a.launchUrl)}" target="_blank" rel="noopener noreferrer">Launch app ${icon('arrow')}</a>`:''}`,
  `${a.canEdit?btn('Retire','retire',`data-id="${a.id}"`,'ghost'):''}${a.canEdit?btn('Edit knowledge','edit',`data-id="${a.id}"`,'','book'):''}${a.scopeId!==a.ownerId&&a.status!=='retired'?btn('Recertify','promote',`data-id="${a.id}" data-target="${a.scopeId}"`,''):''}${target&&a.status!=='retired'?btn('Propose promotion','promote',`data-id="${a.id}"`,'primary','arrow'):''}`);
}
function itemFields(a={}){return `<div class="form-field"><label for="item-title">Title</label><input id="item-title" name="title" required maxlength="160" value="${esc(a.title||'')}" placeholder="A clear, reusable piece of knowledge"></div><div class="form-grid"><div class="form-field"><label for="item-kind">Type</label><select id="item-kind" name="kind">${['knowledge','standard','skill','app'].map(k=>`<option value="${k}" ${a.kind===k?'selected':''}>${label(k)}</option>`).join('')}</select></div><div class="form-field"><label for="item-authority">Intended authority</label><select id="item-authority" name="authority">${['reference','guidance','mandatory'].map(k=>`<option ${a.authority===k?'selected':''}>${k}</option>`).join('')}</select></div></div><div class="form-field" style="margin-top:16px"><label for="item-content">Knowledge / instructions / app description</label><textarea id="item-content" name="content" required rows="7" maxlength="20000">${esc(a.content||'')}</textarea><small>Mandatory authority takes effect only after scoped certification.</small></div><div class="form-field"><label for="item-tags">Topics · comma separated</label><input id="item-tags" name="tags" value="${esc((a.tags||[]).join(', '))}" placeholder="reconciliation, audit, finance"></div><div class="form-grid"><div class="form-field"><label for="rule-key">Optional conflict key</label><input id="rule-key" name="ruleKey" value="${esc(a.ruleKey||'')}" placeholder="reconciliation.evidence_days"></div><div class="form-field"><label for="rule-value">Assertion value</label><input id="rule-value" name="ruleValue" value="${esc(a.ruleValue||'')}" placeholder="90"></div></div><details style="margin-top:18px;padding:12px 0"><summary>App settings</summary><div class="form-field" style="margin-top:12px"><label for="launch-url">Optional launch URL</label><input id="launch-url" name="launchUrl" type="url" value="${esc(a.launchUrl||'')}" placeholder="https://approved-app.example"></div><div class="form-field"><label for="dependencies">Required knowledge · select multiple with Ctrl / Cmd</label><select id="dependencies" name="dependencies" multiple size="4">${boot.assets.filter(x=>x.kind!=='app'&&x.id!==a.id).map(x=>`<option value="${x.id}" ${(a.dependencies||[]).includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div></details><label class="checkbox"><input name="tetherable" type="checkbox" ${a.tetherable?'checked':''}>Eligible for topic tether sharing after certification and agreement by both scopes.</label>`;}
function editItem(id,type){const a=id?getAsset(id):{kind:type||'knowledge'};modal(id?'Revise knowledge':type==='app'?'Register a personal app':'Capture knowledge',id?'Editing a certified item will trigger recertification.':'New knowledge starts in your private workspace.',`<form id="item-form" data-id="${id||''}">${itemFields(a)}${id?`<input type="hidden" name="version" value="${a.version}">`:''}</form>`,`${btn('Cancel','close','','ghost')}<button type="submit" form="item-form" class="btn primary">${icon('check')}${id?'Save new version':'Save privately'}</button>`);}
function promote(id,target){const a=getAsset(id),targetId=target||(a.scopeId===a.ownerId?boot.user.unitId:boot.units.find(u=>u.id===a.scopeId)?.parentId);if(!targetId)return toast('There is no broader scope above this item.',true);
  modal(target===a.scopeId?'Request recertification':'Propose a shared standard',`${esc(scopeName(a.scopeId))} → ${esc(scopeName(targetId))}`,`<form id="promotion-form" data-id="${a.id}" data-target="${targetId}"><div class="notice">Edit the version you want this audience to use. Your original remains intact. The reviewer will see the full before-and-after diff.</div>${itemFields(a)}<div class="form-field"><label for="rationale">Why should this become shared practice?</label><textarea id="rationale" name="rationale" rows="2" required placeholder="What recurring problem does it solve?"></textarea></div><div class="form-field"><label for="evidence">Review evidence</label><textarea id="evidence" name="evidence" rows="2" required placeholder="Examples, validation, or links that support certification"></textarea></div><label class="checkbox"><input name="consent" type="checkbox" required>I explicitly submit this text and evidence to the ${esc(scopeName(targetId))} reviewers and authorize the approved text to become available to that audience.</label></form>`,`${btn('Cancel','close','','ghost')}<button class="btn primary" type="submit" form="promotion-form">${icon('review')} Submit for review</button>`);
}
function lineDiff(before,after){const A=before.split('\n'),B=after.split('\n');if(A.length>350||B.length>350)return {html:`<div class="diff-cell del">${esc(before)}</div><div class="diff-cell add">${esc(after)}</div>`,adds:B.length,deletes:A.length};const dp=Array.from({length:A.length+1},()=>new Uint16Array(B.length+1));for(let i=A.length-1;i>=0;i--)for(let j=B.length-1;j>=0;j--)dp[i][j]=A[i]===B[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);let i=0,j=0,html='',adds=0,deletes=0;while(i<A.length||j<B.length){if(i<A.length&&j<B.length&&A[i]===B[j]){html+=`<div class="diff-cell">  ${esc(A[i++])}</div><div class="diff-cell">  ${esc(B[j++])}</div>`;}else if(i<A.length&&(j===B.length||dp[i+1][j]>=dp[i][j+1])){html+=`<div class="diff-cell del">− ${esc(A[i++])}</div><div class="diff-cell blank"> </div>`;deletes++;}else{html+=`<div class="diff-cell blank"> </div><div class="diff-cell add">+ ${esc(B[j++])}</div>`;adds++;}}return{html,adds,deletes};}
function review(id){const p=boot.proposals.find(x=>x.id===id);if(!p)return;const diff=lineDiff(p.before.content,p.proposed.content),source=getAsset(p.assetId),stale=source&&source.version!==p.sourceVersion;const changed=['title','kind','authority','tags','ruleKey','ruleValue','tetherable','dependencies','launchUrl'].filter(k=>JSON.stringify(p.before[k])!==JSON.stringify(p.proposed[k]));const targetManager=boot.units.find(u=>u.id===p.targetId)?.managerId;
  modal(esc(p.proposed.title),`Submitted by ${esc(userName(p.submittedBy))} · source v${p.sourceVersion} · ${date(p.submittedAt)}`,`<div class="status-line">${badge(label(p.status),stateColor(p.status))}${badge(scopeName(p.before.scopeId),'grey')}${icon('arrow')}${badge(scopeName(p.targetId),'blue')}</div>${stale?'<div class="notice red">The source has changed since submission. A fresh proposal is required.</div>':''}<div class="review-note"><strong>Why this should be shared</strong><br>${esc(p.rationale)}</div><div class="review-note"><strong>Review evidence</strong><br>${esc(p.evidence)}</div><div class="review-metadata">${badge(`+${diff.adds} lines`,'green')}${badge(`−${diff.deletes} lines`,'red')}${changed.map(k=>badge(`${label(k)} changed`,'amber')).join('')}</div><div class="diff-head"><div>Current / source snapshot</div><div>Proposed for ${esc(scopeName(p.targetId))}</div></div><div class="diff">${diff.html}</div>${changed.length?`<div class="mini-label">Metadata changes</div><div class="table-wrap"><table class="data-table" style="min-width:0"><thead><tr><th>Field</th><th>Before</th><th>Proposed</th></tr></thead><tbody>${changed.map(k=>`<tr><td>${label(k)}</td><td>${esc(p.before[k])}</td><td>${esc(p.proposed[k])}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="notice ${p.proposed.authority==='mandatory'?'amber':''}"><strong>${esc(p.proposed.authority)} authority</strong> · ${p.proposed.tetherable?'Eligible for explicit topic tethers':'No tether sharing'}<br>Approval publishes this reviewed text to ${esc(scopeName(p.targetId))}. It does not publish unrelated personal knowledge.</div>${p.history.length?`<div class="mini-label">Decision history</div>${p.history.map(h=>`<div class="review-note"><strong>${esc(userName(h.by))} · ${label(h.decision)}</strong><br>${esc(h.comment)}<div class="tiny muted">${new Date(h.at).toLocaleString()}</div></div>`).join('')}`:''}${p.status==='pending'&&p.canReview?`<div class="form-field"><label for="review-comment">Decision rationale</label><textarea id="review-comment" rows="3" required placeholder="Explain the approval, or what needs to change."></textarea></div><div class="form-field"><label for="valid-days">Certification duration</label><select id="valid-days"><option value="180">180 days</option><option value="90">90 days</option><option value="30">30 days</option><option value="365">365 days</option></select></div>`:p.status==='pending'?`<div class="notice">This proposal is awaiting a separate reviewer. ${esc(userName(targetManager))} or an active delegate can review it.${boot.mode==='demo'?' Use the demo identity switch to try that role.':''}</div>`:''}`,p.status==='pending'&&p.canReview?`${btn('Reject','review-decision',`data-id="${p.id}" data-decision="reject"`,'danger')}${btn('Request changes','review-decision',`data-id="${p.id}" data-decision="request_changes"`)}${btn('Approve & certify','review-decision',`data-id="${p.id}" data-decision="approve"`,'primary','check')}`:p.status==='pending'&&p.submittedBy===boot.user.id?`${btn('Withdraw submission','withdraw',`data-id="${p.id}"`,'ghost')}${btn('Close','close')}`:btn('Close','close'), 'REVIEW THE CHANGE');
}
function sourceModal(id){const c=boot.connectors.find(x=>x.id===id),result=sourceResults[id];modal(c.name,'A guided connection path, with explicit source boundaries.',`<div class="status-line">${badge(c.route,'blue')}${badge(c.baseUrl?'URL configured':'Not connected',c.baseUrl?'amber':'grey')}</div><p class="small muted">${esc(c.note)}</p><div class="mini-label">What is needed</div><ul class="list-plain">${c.needs.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>${c.capability==='live_inventory'?`<form id="source-form" data-id="${id}"><div class="form-field"><label for="source-url">Instance URL · host only, including a self-hosted path if required</label><input name="baseUrl" id="source-url" type="url" placeholder="https://your-company.atlassian.net" value="${esc(c.baseUrl)}" ${boot.isAdmin?'':'readonly'}><small>Server credentials are configured per user; secrets are never stored in this form.</small></div>${boot.isAdmin?'<button class="btn" type="submit">Save connection settings</button>':'<p class="tiny muted">The organization standards owner configures source URLs.</p>'}</form><div class="button-row" style="margin-top:18px">${btn('Discover accessible metadata','discover',`data-id="${id}"`,'primary','search')}${c.docs?`<a class="btn ghost" href="${esc(c.docs)}" target="_blank" rel="noopener noreferrer">API documentation ↗</a>`:''}</div>`:''}<div class="notice">Credentials and host allowlisting must be configured by the deployment owner. Discovery reads up to 25 accessible metadata records; it does not promote or auto-import them.</div>${result?`<div class="mini-label">Live inventory · ${result.items.length} records</div>${result.items.map(i=>`<div class="grant-row"><div><strong class="small">${esc(i.title)}</strong><div class="tiny muted">${esc(i.externalId)} · ${esc(i.summary)}</div></div></div>`).join('')||'<p class="small muted">No accessible records returned.</p>'}${result.truncated?'<p class="tiny muted">More records may exist. This is a bounded discovery sample.</p>':''}`:''}<hr class="separator"><div class="mini-label">Import a normalized export</div><p class="small muted">Each record becomes private knowledge. The same external ID with a new revision updates its snapshot and invalidates derived certifications.</p><div class="button-row"><label class="btn">${icon('download')} Choose JSON file<input type="file" accept="application/json,.json" data-source="${id}" id="import-file" hidden></label>${btn('Download example','import-example',`data-id="${id}"`,'ghost')}</div>`,btn('Done','close'));
}
function delegateModal(){const units=boot.units.filter(u=>u.managerId===boot.user.id);if(!units.length)return toast('Only a named scope manager can appoint delegates.',true);modal('Appoint an approval delegate','Delegate review authority for a specific scope and duration.',`<form id="delegate-form"><div class="form-field"><label>Scope</label><select name="unitId">${units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></div><div class="form-field"><label>Person</label><select name="userId">${boot.users.filter(u=>u.id!==boot.user.id).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select><small>The server verifies that the person belongs to the selected scope.</small></div><div class="form-field"><label>Duration in days</label><input name="days" type="number" min="1" max="365" value="90" required></div></form>`,`${btn('Cancel','close','','ghost')}<button class="btn primary" form="delegate-form" type="submit">Appoint delegate</button>`);}
function tetherModal(){const units=boot.units.filter(u=>boot.managedUnits.includes(u.id));if(!units.length)return toast('A source-scope manager or delegate must propose a tether.',true);modal('Propose a knowledge tether','Share specific topics without changing anyone’s team membership.',`<form id="tether-form"><div class="form-grid"><div class="form-field"><label>From scope</label><select name="fromId">${units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></div><div class="form-field"><label>To scope</label><select name="toId">${boot.units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></div></div><div class="form-field" style="margin-top:17px"><label>Shared topics</label><input name="tags" placeholder="reconciliation, audit" required></div><div class="notice">A destination manager must accept. Only certified knowledge approved for tether sharing becomes available. A tether does not impose source-scope standards on the destination.</div></form>`,`${btn('Cancel','close','','ghost')}<button class="btn primary" form="tether-form" type="submit">Propose agreement</button>`);}
function fields(form){const f=new FormData(form);return{title:f.get('title'),kind:f.get('kind'),authority:f.get('authority'),content:f.get('content'),tags:String(f.get('tags')).split(',').map(s=>s.trim()).filter(Boolean),ruleKey:f.get('ruleKey'),ruleValue:f.get('ruleValue'),tetherable:f.get('tetherable')==='on',launchUrl:f.get('launchUrl'),dependencies:f.getAll('dependencies')};}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function resolveForm(form){const f=new FormData(form);packet=await api('/context/resolve',{prompt:f.get('prompt'),scope:f.get('scope'),appId:f.get('appId')||undefined,budget:Number(f.get('budget'))});$('#resolution').innerHTML=packetView(packet);boot.events=await api('/events');}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id}=el.dataset;
  try{
    if(action==='nav')return navigate(el.dataset.view);
    if(action==='close')return close();
    if(action==='filter'){filter=el.dataset.filter;return render();}
    if(action==='scope'){view='knowledge';filter=el.dataset.scope;return render();}
    if(action==='new-item')return editItem();
    if(action==='new-app')return editItem(null,'app');
    if(action==='edit')return editItem(id);
    if(action==='detail')return detail(id);
    if(action==='promote')return promote(id,el.dataset.target);
    if(action==='review')return review(id);
    if(action==='source')return sourceModal(id);
    if(action==='new-delegate')return delegateModal();
    if(action==='new-tether')return tetherModal();
    if(action==='example'){$('#prompt').value=el.dataset.prompt;$('#prompt').focus();return;}
    if(action==='try-prompt'){packet=null;navigate('context');$('#prompt').value=el.dataset.prompt;return;}
    if(action==='app-context'){const a=getAsset(id);packet=null;navigate('context');$('#context-app').value=id;$('#prompt').value=`Help me with ${a.tags.join(' and ')}`;return;}
    if(action==='export-packet')return download('dreamcatcher-context-packet.json',packet);
    if(action==='packet-json')return modal('Context delivery contract','Structured evidence for the AI client.',`<pre>${esc(JSON.stringify(packet,null,2))}</pre>`,btn('Close','close'));
    if(action==='demo-help')return modal('Try the complete review flow','The workspace uses synthetic people and illustrative policies.',`<ol class="list-plain"><li>As Paul, open Context playground and ask “Latest Jira tickets.” Inspect the personal query plan.</li><li>Ask about reconciliation evidence. See the team standard constrain the personal 30-day note.</li><li>Open Promotion reviews and inspect the pending checklist submission.</li><li>Switch the demo identity to Sam Chen or Avery Reed.</li><li>Review the diff, enter a rationale, and approve the team standard.</li><li>Switch back to Paul and resolve the same request again.</li></ol><div class="notice">Changes persist in the local database. The reset command restores the sample workspace.</div>`,btn('Got it','close','','primary'));
    el.disabled=true;
    if(action==='review-decision'){const p=boot.proposals.find(x=>x.id===id);await api(`/promotions/${id}/review`,{decision:el.dataset.decision,revision:p.revision,comment:$('#review-comment').value,validDays:Number($('#valid-days').value)});close();await refresh();toast('Decision recorded. The review history is preserved.');}
    if(action==='withdraw'){await api(`/promotions/${id}/withdraw`,{});close();await refresh();toast('Submission withdrawn. You can revise and resubmit.');}
    if(action==='retire'){modal('Retire this knowledge?',esc(getAsset(id).title),'<p class="small muted">It will stop being retrieved. Derived certifications will require review.</p>',`${btn('Cancel','close','','ghost')}${btn('Retire item','confirm-retire',`data-id="${id}"`,'danger')}`);}
    if(action==='confirm-retire'){await api(`/knowledge/${id}/retire`,{});close();await refresh();toast('Item retired.');}
    if(action==='accept-tether'||action==='revoke-tether'){await api(`/tethers/${id}`,{decision:action==='accept-tether'?'accept':'revoke'});await refresh();toast('Sharing agreement updated.');}
    if(action==='revoke-delegate'){await api(`/delegations/${id}/revoke`,{});await refresh();toast('Delegation revoked.');}
    if(action==='discover'){sourceResults[id]=await api(`/connectors/${id}/discover`,{});sourceModal(id);toast('Live inventory retrieved. No records were imported.');}
    if(action==='import-example')download(`${id}-normalized-example.json`,{records:[{externalId:'EXAMPLE-001',revision:'1',title:'Example source knowledge',content:'Replace this with an authorized source excerpt.',tags:[id],kind:'knowledge',uri:''}]});
    if(action==='show-bridge'||action==='export-bridge'){bridgeConfig=await api('/bifrost-config');if(action==='export-bridge')download('bifrost-context-config.json',bridgeConfig);else modal('Bifrost MCP configuration',boot.mode==='demo'?'Local synthetic demo only. Use per-user authentication for a shared deployment.':'Use a unique per-user bearer credential.',`<pre>${esc(JSON.stringify(bridgeConfig,null,2))}</pre><div class="notice">If Bifrost runs in a container, localhost refers to that container. Use the service’s reachable private address. In authenticated mode, each person supplies <code>Authorization: Bearer &lt;their-token&gt;</code>.</div>`,btn('Close','close'));}
  }catch(error){toast(error.message,true);}finally{el.disabled=false;}
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,submit=event.submitter;if(submit)submit.disabled=true;
  try{
    if(form.id==='resolve-form')await resolveForm(form);
    if(form.id==='item-form'){const payload=fields(form),id=form.dataset.id;if(id)payload.version=Number(new FormData(form).get('version'));await api(id?`/knowledge/${id}`:'/knowledge',payload,id?'PUT':'POST');close();await refresh();toast(id?'New version saved. Certifications refreshed for review.':'Saved to your private workspace.');}
    if(form.id==='promotion-form'){const f=new FormData(form),a=getAsset(form.dataset.id);await api('/promotions',{assetId:a.id,version:a.version,targetId:form.dataset.target,proposed:fields(form),rationale:f.get('rationale'),evidence:f.get('evidence'),publishConsent:f.get('consent')==='on'});close();view='reviews';filter='all';await refresh();toast('Submitted to the target manager or delegate.');}
    if(form.id==='delegate-form'){const f=new FormData(form);await api('/delegations',{unitId:f.get('unitId'),userId:f.get('userId'),days:Number(f.get('days'))});close();await refresh();toast('Approval delegate appointed.');}
    if(form.id==='tether-form'){const f=new FormData(form);await api('/tethers',{fromId:f.get('fromId'),toId:f.get('toId'),tags:String(f.get('tags')).split(',')});close();await refresh();toast('Tether proposed. A destination manager must accept.');}
    if(form.id==='source-form'){await api(`/connectors/${form.dataset.id}`,{baseUrl:new FormData(form).get('baseUrl')},'PUT');await refresh();sourceModal(form.dataset.id);toast('Connection URL saved. Credentials remain server-side.');}
    if(form.id==='login-form'){token=new FormData(form).get('token');await refresh();}
  }catch(error){toast(error.message,true);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',event=>{if(event.target.id==='knowledge-search'){query=event.target.value;$('#registry-table').innerHTML=registryTable();}});
document.addEventListener('change',async event=>{
  try{
    if(event.target.id==='identity'){demoUser=event.target.value;sessionStorage.setItem('dc_demo_user',demoUser);packet=null;close();await refresh();toast(`Now exploring as ${boot.user.name}`);}
    if(event.target.id==='kind-filter'){kindFilter=event.target.value;$('#registry-table').innerHTML=registryTable();}
    if(event.target.id==='import-file'){const file=event.target.files[0];if(!file)return;if(file.size>900000)throw new Error('Import file must be smaller than 900 KB');const parsed=JSON.parse(await file.text());const r=await api(`/connectors/${event.target.dataset.source}/import`,parsed);close();view='knowledge';await refresh();toast(`${r.imported.length} source records imported privately.`);}
  }catch(error){toast(error.message,true);}
});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-action][tabindex]')){event.preventDefault();event.target.click();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
async function init(){try{const mode=await api('/mode');view=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'overview';if(!mode.demo){$('#app').innerHTML=`<form class="panel login" id="login-form"><img src="/favicon.svg" alt=""><h1>Dreamcatcher Context</h1><p class="muted">Use the per-user credential supplied by your deployment owner.</p><div class="form-field"><label for="auth-token">Access token</label><input id="auth-token" name="token" type="password" autocomplete="off" required></div><button class="btn primary full" type="submit">Open workspace</button><p class="tiny muted">The token stays in this page’s memory and is cleared when you reload.</p></form>`;return;}await refresh();}catch(error){$('#app').innerHTML=`<div class="panel login"><h1>Could not open the workspace</h1><p class="muted">${esc(error.message)}</p>${btn('Retry','reload','','primary')}</div>`;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reload"]'))location.reload();});
init();
